def veh_block(s):
    v = VEH[s]
    return {'vehicle_id': v['vehicle_id'], 'vin': v['vin'], 'license_plate': v['plate'], 'fleet_id': v['fleet'],
            'mileage_km': v['km'], 'operating_hours': v['hours']}
def eng_block(s):
    return {'engine_id': VEH[s]['engine_id'], 'code': ENGINE_CODE}
def requester(s):
    m = MECH[VEH[s]['mech']]
    return {'user_id': m['user_id'], 'name': m['name'], 'role': 'mechanic'}

def sumhours(items):
    return round(sum(i.get('norm_hours_adjusted', 0) or 0 for i in items), 2)

